#include <vector>

using namespace std;

class Solution {
public:
    int maximumPopulation(vector<vector<int>>& logs) {
        vector<int> pop(101);
        for (auto& l : logs) {
            pop[l[0] - 1950]++;
            pop[l[1] - 1950]--;
        }
        int maxYear = 1950, maxPop = pop[0];
        for (int i = 1; i < 101; ++i) {
            pop[i] += pop[i - 1];
            if (pop[i] > maxPop) {
                maxPop = pop[i];
                maxYear = 1950 + i;
            }
        }
        return maxYear;
    }
};
